versions.variantCss:
.wemd-full-quote[data-variant="bytedance-fullquote-bold"] {
  background: linear-gradient(135deg, var(--wemd-bg-soft), var(--wemd-bg-muted));
  border-radius: var(--wemd-border-radius);
  padding: 32px 28px;
  margin: 24px 0;
  text-align: center;
  border-left: 4px solid var(--wemd-primary);
}
.wemd-full-quote[data-variant="bytedance-fullquote-bold"] .wemd-fq-text {
  color: var(--wemd-text-strong);
  font-size: 20px;
  font-weight: 700;
  font-style: italic;
  line-height: 1.6;
  margin: 0;
}
